module asyn_fifo(
    input wclk, rclk, wrstn, rrstn, winc, rinc,
    input [WIDTH-1:0] wdata,
    output wfull, rempty,
    output [WIDTH-1:0] rdata
);
    parameter WIDTH = 8;
    parameter DEPTH = 16;
    parameter ADDR_WIDTH = $clog2(DEPTH);
    reg [ADDR_WIDTH:0] raddr_bin;
    reg [ADDR_WIDTH:0] raddr_gray;
    reg [ADDR_WIDTH:0] rptr;
    reg [ADDR_WIDTH:0] rptr_buff;
    reg [ADDR_WIDTH:0] rptr_syn;
    reg ren;
    reg [ADDR_WIDTH:0] waddr_bin;
    reg [ADDR_WIDTH:0] waddr_gray;
    reg [ADDR_WIDTH:0] wptr;
    reg [ADDR_WIDTH:0] wptr_buff;
    reg [ADDR_WIDTH:0] wptr_syn;
    reg wen;
    reg rempty;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= {ADDR_WIDTH{1'b0}};
        end else if (!rempty && rinc) begin
            raddr_bin <= raddr_bin + 1;
        end
    end
    assign raddr_gray = raddr_bin ^ (raddr_bin >> 1);
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr <= {ADDR_WIDTH{1'b0}};
        end else begin
            rptr <= raddr_gray;
        end
    end
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_buff <= {ADDR_WIDTH{1'b0}};
        end else begin
            wptr_buff <= wptr;
        end
    end
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_syn <= {ADDR_WIDTH{1'b0}};
        end else begin
            wptr_syn <= wptr_buff;
        end
    end
    assign wfull = (wptr == ~{rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= {ADDR_WIDTH{1'b0}};
        end else if (!wfull && winc) begin
            waddr_bin <= waddr_bin + 1;
        end
    end
    assign waddr_gray = waddr_bin ^ (waddr_bin >> 1);
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr <= {ADDR_WIDTH{1'b0}};
        end else begin
            wptr <= waddr_gray;
        end
    end
    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rempty <= 1'b1;
        end else begin
            rempty <= (rptr == wptr_syn);
        end
    end
    dual_port_RAM #(WIDTH, DEPTH) dual_port_RAM_inst(
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );
endmodule
